import json
import os
from typing import Callable, Optional

from azure.servicebus import ServiceBusClient, ServiceBusMessage, ServiceBusReceiveMode
from azure.servicebus.exceptions import ServiceBusError


class DeadLetterPublisher:
    def __init__(
        self,
        connection_string: Optional[str] = None,
        source_queue_name: Optional[str] = None,
        dead_letter_queue_name: Optional[str] = None,
    ):
        self.connection_string = connection_string or os.environ.get(
            "AZURE_SERVICE_BUS_CONNECTION_STRING"
        )
        self.source_queue_name = source_queue_name or os.environ.get("AZURE_SERVICE_BUS_SOURCE_QUEUE")
        self.dead_letter_queue_name = dead_letter_queue_name or os.environ.get(
            "AZURE_SERVICE_BUS_DEAD_LETTER_QUEUE"
        )

        if not self.connection_string:
            raise ValueError("Missing Azure Service Bus connection string.")
        if not self.source_queue_name:
            raise ValueError("Missing Azure Service Bus source queue name.")
        if not self.dead_letter_queue_name:
            raise ValueError("Missing Azure Service Bus dead-letter queue name.")

        self.client = ServiceBusClient.from_connection_string(self.connection_string)

    def _send_to_dead_letter(self, body: bytes, reason: str, error: str, original_message_id: Optional[str] = None):
        payload = {
            "original_message_id": original_message_id,
            "reason": reason,
            "error": error,
            "body": body.decode("utf-8", errors="replace"),
        }
        message = ServiceBusMessage(
            json.dumps(payload),
            content_type="application/json",
            subject="dead-letter",
        )
        with self.client.get_queue_sender(queue_name=self.dead_letter_queue_name) as sender:
            sender.send_messages(message)

    def process_messages(
        self,
        handler: Callable[[bytes], None],
        max_messages: int = 10,
        max_wait_time: int = 5,
    ) -> None:
        with self.client.get_queue_receiver(
            queue_name=self.source_queue_name,
            receive_mode=ServiceBusReceiveMode.PEEK_LOCK,
        ) as receiver:
            messages = receiver.receive_messages(max_message_count=max_messages, max_wait_time=max_wait_time)
            for msg in messages:
                try:
                    body_bytes = b"".join(
                        part if isinstance(part, bytes) else str(part).encode("utf-8")
                        for part in msg.body
                    )
                    handler(body_bytes)
                    receiver.complete_message(msg)
                except Exception as exc:
                    try:
                        self._send_to_dead_letter(
                            body=body_bytes if "body_bytes" in locals() else b"",
                            reason="processing_failed",
                            error=f"{type(exc).__name__}: {exc}",
                            original_message_id=getattr(msg, "message_id", None),
                        )
                    finally:
                        try:
                            receiver.abandon_message(msg)
                        except ServiceBusError:
                            pass


def process_failed_messages_to_dead_letter(
    handler: Callable[[bytes], None],
    connection_string: Optional[str] = None,
    source_queue_name: Optional[str] = None,
    dead_letter_queue_name: Optional[str] = None,
    max_messages: int = 10,
    max_wait_time: int = 5,
) -> None:
    publisher = DeadLetterPublisher(
        connection_string=connection_string,
        source_queue_name=source_queue_name,
        dead_letter_queue_name=dead_letter_queue_name,
    )
    publisher.process_messages(
        handler=handler,
        max_messages=max_messages,
        max_wait_time=max_wait_time,
    )
